changeSet.sql:
CREATE FUNCTION revise_tracks_after_geometry_change()
RETURNS trigger AS $$
BEGIN
  -- Each stored variant is one row; individual GPS points do not invoke this.
  -- The existing parent trigger owns the actual version increment.
  IF TG_OP = 'INSERT' THEN
    UPDATE gps_track SET version = version
     WHERE id IN (SELECT DISTINCT gps_track_id FROM new_geometry);
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE gps_track SET version = version
     WHERE id IN (SELECT DISTINCT gps_track_id FROM old_geometry);
  ELSE
    UPDATE gps_track SET version = version
     WHERE id IN (
       SELECT gps_track_id FROM old_geometry
       UNION
       SELECT gps_track_id FROM new_geometry
     );
  END IF;
  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

changeSet.rollback:
DROP TRIGGER gps_track_geometry_insert_revision ON gps_track_data;
DROP TRIGGER gps_track_geometry_update_revision ON gps_track_data;
DROP TRIGGER gps_track_geometry_delete_revision ON gps_track_data;
DROP FUNCTION revise_tracks_after_geometry_change();
